use vstd::prelude::*;

verus! {

// Specification function to check if an integer is odd
spec fn is_odd(n: i32) -> bool {
    n % 2 != 0
}

// Specification function to check if all elements before index are not odd
spec fn all_not_odd_before(a: Seq<i32>, index: int) -> bool {
    forall|i: int| 0 <= i < index ==> !is_odd(a[i])
}

fn find_first_odd(a: &Vec<i32>) -> (result: Option<usize>)
    requires
        a.len() > 0,
    ensures
        match result {
            Some(index) => {
                // index is valid
                &&& index < a.len()
                // element at index is odd
                &&& is_odd(a[index as int])
                // all elements before index are not odd
                &&& all_not_odd_before(a@, index as int)
            },
            None => {
                // all elements are not odd
                forall|i: int| 0 <= i < a.len() ==> !is_odd(a[i])
            }
        }
{
    let mut idx: usize = 0;
    
    while idx < a.len()
        invariant
            idx <= a.len(),
            // All elements before idx are not odd
            all_not_odd_before(a@, idx as int),
    {
        if a[idx] % 2 != 0 {
            // Found an odd element
            assert(is_odd(a[idx as int]));
            return Some(idx);
        }
        
        // Current element is not odd, move to next
        assert(!is_odd(a[idx as int]));
        idx = idx + 1;
    }
    
    // No odd element found
    assert(idx == a.len());
    assert(forall|i: int| 0 <= i < a.len() ==> !is_odd(a[i])) by {
        assert(all_not_odd_before(a@, a.len() as int));
    }
    
    None
}

}

